CREATE TABLE IF NOT EXISTS process_instances (instance_id TEXT PRIMARY KEY, process_id TEXT NOT NULL, version_id TEXT NOT NULL, engine_instance_key TEXT, status TEXT NOT NULL, current_state_json TEXT NOT NULL, created_at TEXT DEFAULT CURRENT_TIMESTAMP, updated_at TEXT DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(process_id) REFERENCES processes(process_id));
CREATE TABLE IF NOT EXISTS temporal_facts (fact_id TEXT PRIMARY KEY, process_id TEXT NOT NULL, instance_id TEXT, fact_type TEXT NOT NULL, valid_from TEXT, valid_until TEXT, payload_json TEXT NOT NULL, created_at TEXT DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(process_id) REFERENCES processes(process_id));
CREATE TABLE IF NOT EXISTS planner_runs (planner_run_id TEXT PRIMARY KEY, run_id TEXT NOT NULL, initial_state_id TEXT NOT NULL, strategy TEXT, termination_status TEXT NOT NULL, limits_json TEXT NOT NULL, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS planner_states (planner_run_id TEXT NOT NULL, state_id TEXT NOT NULL, parent_state_id TEXT, depth INTEGER NOT NULL, cost_time REAL NOT NULL, cost_budget REAL NOT NULL, cost_risk REAL NOT NULL, payload_json TEXT NOT NULL, PRIMARY KEY(planner_run_id,state_id));
CREATE TABLE IF NOT EXISTS temporal_plans (plan_id TEXT PRIMARY KEY, planner_run_id TEXT NOT NULL, strategy TEXT NOT NULL, selected INTEGER NOT NULL DEFAULT 0, score REAL, payload_json TEXT NOT NULL, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS validation_reports (validation_id TEXT PRIMARY KEY, run_id TEXT NOT NULL, candidate_id TEXT, validator_id TEXT NOT NULL, validator_version TEXT NOT NULL, status TEXT NOT NULL, input_checksum TEXT NOT NULL, output_checksum TEXT, payload_json TEXT NOT NULL, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS engine_deployments (deployment_id TEXT PRIMARY KEY, run_id TEXT NOT NULL, engine_type TEXT NOT NULL, remote_key TEXT, process_definition_key TEXT, status TEXT NOT NULL, request_hash TEXT NOT NULL, payload_json TEXT NOT NULL, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS engine_migrations (migration_id TEXT PRIMARY KEY, run_id TEXT NOT NULL, deployment_id TEXT, instance_id TEXT NOT NULL, idempotency_key TEXT NOT NULL UNIQUE, status TEXT NOT NULL, payload_json TEXT NOT NULL, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS embedding_manifests (manifest_id TEXT PRIMARY KEY, backend TEXT NOT NULL, model_name TEXT NOT NULL, model_revision TEXT NOT NULL, dimensions INTEGER NOT NULL, content_checksum TEXT NOT NULL, index_version TEXT NOT NULL, payload_json TEXT NOT NULL, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS experiment_observations (observation_id TEXT PRIMARY KEY, experiment_id TEXT NOT NULL, scenario_id TEXT NOT NULL, variant TEXT NOT NULL, repetition INTEGER NOT NULL, seed INTEGER NOT NULL, status TEXT NOT NULL, payload_json TEXT NOT NULL, created_at TEXT DEFAULT CURRENT_TIMESTAMP, UNIQUE(experiment_id,scenario_id,variant,repetition));
CREATE TABLE IF NOT EXISTS approvals (approval_id TEXT PRIMARY KEY, run_id TEXT NOT NULL, approval_type TEXT NOT NULL, actor TEXT NOT NULL, decision TEXT NOT NULL, reason TEXT NOT NULL, signature TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS evidence_artifacts (artifact_id TEXT PRIMARY KEY, run_id TEXT, experiment_id TEXT, artifact_type TEXT NOT NULL, path TEXT NOT NULL, checksum TEXT NOT NULL, metadata_json TEXT NOT NULL, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_temporal_facts_scope ON temporal_facts(process_id,instance_id,fact_type);
CREATE INDEX IF NOT EXISTS idx_validation_run ON validation_reports(run_id,validator_id,status);
CREATE INDEX IF NOT EXISTS idx_observations_experiment ON experiment_observations(experiment_id,variant,scenario_id);
